<template><div class="vs-table-wrap" :aria-busy="loading || undefined"><LoadingSkeleton v-if="loading" variant="table" :lines="skeletonRows"/><EmptyState v-else-if="error" kind="error" title="Không thể tải dữ liệu" :description="error"><template #actions><slot name="retry"/></template></EmptyState><EmptyState v-else-if="permissionDenied" kind="permission" title="Bạn không có quyền xem dữ liệu này" description="Liên hệ quản trị viên nếu bạn cần quyền truy cập."/><EmptyState v-else-if="!rows.length" :title="emptyTitle" :description="emptyDescription"><template #actions><slot name="empty-actions"/></template></EmptyState><div v-else class="vs-table-scroll" tabindex="0" aria-label="Bảng dữ liệu có thể cuộn ngang"><table><thead><tr><th v-for="column in columns" :key="column.key" scope="col" :aria-sort="sortKey===column.key?(sortDirection==='asc'?'ascending':'descending'):undefined"><button v-if="column.sortable" type="button" @click="$emit('sort',column.key)">{{column.label}}<span aria-hidden="true">{{sortKey===column.key?(sortDirection==='asc'?' ↑':' ↓'):''}}</span></button><span v-else>{{column.label}}</span></th><th v-if="$slots.actions" scope="col"><span class="sr-only">Thao tác dòng</span></th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row[rowKey]??index"><td v-for="column in columns" :key="column.key" :data-label="column.label"><slot :name="`cell-${column.key}`" :row="row" :value="row[column.key]">{{row[column.key]}}</slot></td><td v-if="$slots.actions" data-label="Thao tác"><slot name="actions" :row="row"/></td></tr></tbody></table></div></div></template>
<script setup>import LoadingSkeleton from './LoadingSkeleton.vue';import EmptyState from './EmptyState.vue';defineProps({columns:{type:Array,required:true},rows:{type:Array,default:()=>[]},rowKey:{type:String,default:'id'},loading:Boolean,error:{type:String,default:''},permissionDenied:Boolean,sortKey:{type:String,default:''},sortDirection:{type:String,default:'asc'},skeletonRows:{type:Number,default:6},emptyTitle:{type:String,default:'Chưa có dữ liệu'},emptyDescription:{type:String,default:'Dữ liệu sẽ xuất hiện tại đây khi có bản ghi phù hợp.'}});defineEmits(['sort'])</script>
<style scoped>.vs-table-wrap{border:1px solid var(--border-subtle);border-radius:var(--radius-card);background:var(--surface-default);overflow:hidden}.vs-table-scroll{overflow:auto}.vs-table-scroll:focus-visible{outline:3px solid color-mix(in srgb,var(--border-focus) 35%,transparent);outline-offset:-3px}table{width:100%;border-collapse:separate;border-spacing:0;color:var(--text-primary);font-size:var(--type-dense-size);line-height:var(--type-dense-line)}thead{position:sticky;top:0;z-index:1;background:var(--surface-subtle)}th,td{height:var(--table-row-height);padding:var(--space-2) var(--space-4);border-bottom:1px solid var(--border-subtle);text-align:left;white-space:nowrap}th{color:var(--text-secondary);font-weight:700}th button{color:inherit;font:inherit;font-weight:inherit}tbody tr:hover{background:var(--surface-hover)}tbody tr:last-child td{border-bottom:0}@media(max-width:640px){.vs-table-scroll{overflow:visible}table,tbody,tr,td{display:block}thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}tr{padding:var(--space-3);border-bottom:1px solid var(--border-subtle)}td{height:auto;min-height:40px;display:grid;grid-template-columns:minmax(110px,40%) 1fr;gap:var(--space-3);padding:var(--space-2);white-space:normal;border:0}td::before{content:attr(data-label);color:var(--text-muted);font-weight:700}}</style>
